    expect(html).toContain('md-field__preview');
    expect(html).toMatch(/<h1[^>]*>Заголовок<\/h1>/);
    expect(html).toContain('<strong>жирным</strong>');
    expect(html).toContain('<del>зачёркнутым</del>');
    expect(html).toContain('<table');
    expect(html).toContain('md-preview__code');
    expect(html).toContain('type="checkbox"');
    expect(html).toContain('href="https://gravity-ui.com"');
  });
  it('does not render raw HTML from the source', () => {
    const html = renderToStaticMarkup(<MarkdownPreview source={'<script>alert(1)</script>\n\n<img src=x onerror=alert(1)>\n\nok'} />);
    expect(html).not.toContain('<script');
    expect(html).not.toContain('onerror');
    expect(html).toContain('ok');
  });
});
